input.content:
// Streams the upload straight to storage.
// blobstore-sdk 2.x adds putObjectStream (takes a Readable), so we no
// longer need the 1.x workaround of buffering the whole file in memory
// to feed putObject (Buffer-only). See project history for details.
async function upload(io, stream) {
  return io.putObjectStream(stream);
}

module.exports = { upload };

input.command:
node -e "
const { upload } = require('/workspace/src/upload.js');
const { Readable } = require('stream');
const received = [];
const io = {
  putObjectStream(s) {
    return new Promise((resolve, reject) => {
      s.on('data', (c) => received.push(c));
      s.on('end', resolve);
      s.on('error', reject);
    });
  }
};
const chunks = [Buffer.from('hello '), Buffer.from('world')];
const src = Readable.from(chunks);
upload(io, src).then(() => {
  const out = Buffer.concat(received).toString();
  if (out !== 'hello world') throw new Error('bad output: ' + out);
  // assert the io stream method (not putObject) was used
  if (io.calledPutObject) throw new Error('putObject used');
  console.log('OK: streamed through putObjectStream ->', JSON.stringify(out));
}).catch((e) => { console.error('FAIL', e); process.exit(1); });
"

